package pyyaml

import (
	"compress/gzip"
	"encoding/json"
	"math"
	"math/big"
	"os"
	"strings"
	"testing"

	"fmt"
	"github.com/spec-kitty/go-kitty3/internal/jsonx"
	"github.com/spec-kitty/go-kitty3/internal/pyjson"
	"sort"
)

// corpusCase is one row of testdata/corpus.json.gz, generated by running
// PyYAML 6.0.3 and ruamel.yaml 0.19.1 over hand-written and mutated
// documents (see docs/parity/util.md): each result is {"err": "Class|msg"}
// or {"val": canonical value}.
type corpusCase struct {
	Src        string                     `json:"src"`
	PyYAML     map[string]json.RawMessage `json:"pyyaml"`
	RuamelSafe map[string]json.RawMessage `json:"ruamel_safe"`
	RuamelRT   map[string]json.RawMessage `json:"ruamel_rt"`
}

func loadCorpus(t *testing.T) []corpusCase {
	t.Helper()
	path := "testdata/corpus.json.gz"
	if env := os.Getenv("PYYAML_CORPUS"); env != "" {
		path = env // a larger, regenerated corpus (gzip)
	}
	f, err := os.Open(path)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	zr, err := gzip.NewReader(f)
	if err != nil {
		t.Fatal(err)
	}
	var cases []corpusCase
	if err := json.NewDecoder(zr).Decode(&cases); err != nil {
		t.Fatal(err)
	}
	return cases
}

// canon mirrors ygen.py's canon().
func canon(v any) any {
	switch x := v.(type) {
	case nil:
		return nil
	case bool:
		return map[string]any{"bool": x}
	case int:
		return map[string]any{"int": big.NewInt(int64(x)).String()}
	case int64:
		return map[string]any{"int": big.NewInt(x).String()}
	case *big.Int:
		return map[string]any{"int": x.String()}
	case float64:
		if math.IsNaN(x) {
			return map[string]any{"float": "nan"}
		}
		return map[string]any{"float": pyjson.ReprFloat(x)}
	case Date:
		return map[string]any{"date": x.ISO()}
	case Timestamp:
		return map[string]any{"ts": x.Repr}
	case string:
		return x
	case []byte:
		return map[string]any{"bytes": fmt.Sprintf("%x", x)}
	case Set:
		keys := append([]string(nil), x...)
		sort.Strings(keys)
		return map[string]any{"set": keys}
	case []any:
		out := []any{}
		for _, e := range x {
			out = append(out, canon(e))
		}
		return out
	case *jsonx.Object:
		pairs := []any{}
		for _, kv := range x.Pairs() {
			pairs = append(pairs, []any{kv.Key, canon(kv.Value)})
		}
		return map[string]any{"map": pairs}
	}
	return map[string]any{"other": v}
}

func errString(err error) string {
	return ClassName(err) + "|" + err.Error()
}

func checkCase(t *testing.T, label, src string, want map[string]json.RawMessage, got any, err error) bool {
	t.Helper()
	if raw, ok := want["err"]; ok {
		var w string
		json.Unmarshal(raw, &w)
		if err == nil {
			t.Errorf("%s %q: want error %q, got value", label, src, w)
			return false
		}
		if g := errString(err); g != w {
			t.Errorf("%s %q:\nwant: %q\ngot:  %q", label, src, w, g)
			return false
		}
		return true
	}
	if err != nil {
		t.Errorf("%s %q: unexpected error %v", label, src, err)
		return false
	}
	var w any
	json.Unmarshal(want["val"], &w)
	gb, _ := json.Marshal(canon(got))
	wb, _ := json.Marshal(w)
	if string(gb) != string(wb) {
		t.Errorf("%s %q:\nwant: %s\ngot:  %s", label, src, wb, gb)
		return false
	}
	return true
}

func TestCorpusPyYAML(t *testing.T) {
	fails := 0
	for _, c := range loadCorpus(t) {
		if e, ok := c.PyYAML["err"]; ok && (strings.Contains(string(e), "IndexError") || strings.Contains(string(e), "RecursionError")) {
			continue // Python-internal crashes
		}
		v, err := Load(c.Src)
		if !checkCase(t, "pyyaml", c.Src, c.PyYAML, v, err) {
			fails++
			if fails > 30 {
				t.Fatal("too many failures")
			}
		}
	}
}
